function PageHeading({ eyebrow, title, description, action }: { eyebrow: string; title: string; description?: string; action?: ReactNode }) {
  return <div className="mb-7 flex flex-wrap items-end justify-between gap-4"><div><div className="text-[10px] font-bold uppercase tracking-[.2em] text-primary">{eyebrow}</div><h1 className="brand mt-2 text-3xl font-bold tracking-[-.05em] md:text-[2.6rem]">{title}</h1>{description && <p className="mt-2 max-w-2xl text-sm text-muted-foreground">{description}</p>}</div>{action}</div>;
}
function PageFrame({ children }: { children: ReactNode }) { return <div className="page-in mx-auto max-w-[1200px] px-4 py-7 md:px-8 md:py-10">{children}</div>; }
function Busy({ label = 'Loading' }: { label?: string }) { return <div className="space-y-4" aria-label={label}>{[0,1,2].map(i=><div key={i} className="h-24 animate-pulse rounded-2xl border border-white/[.05] bg-white/[.035]"/>)}</div>; }
function Retry({ onRetry, text = 'Could not load this yet.' }: { onRetry: () => void; text?: string }) { return <div className="rounded-2xl border border-white/10 bg-card p-7 text-center"><p className="text-sm text-muted-foreground">{text}</p><button onClick={onRetry} data-testid="button-retry" className="mt-4 rounded-lg bg-secondary px-4 py-2 text-sm font-semibold">Try again</button></div>; }
function Avatar({ profile, size = 'md' }: { profile: Profile; size?: 'sm'|'md'|'lg' }) {
  const [broken,setBroken]=useState(false); const src=mediaUrl(profile.photos?.[0]); const classes=size==='lg'?'h-24 w-24 text-2xl':size==='sm'?'h-11 w-11 text-sm':'h-14 w-14 text-lg';
  return <div className={`${classes} shrink-0 overflow-hidden rounded-full bg-[linear-gradient(145deg,#703a58,#302333)] ring-1 ring-white/10`} data-testid={`avatar-${profile.id}`}>{src&&!broken?<MediaImage reference={profile.photos?.[0]} onError={()=>setBroken(true)} className="h-full w-full object-cover" alt={`${profile.name}'s profile`}/>:<span className="flex h-full items-center justify-center font-bold text-[#ffd3e6]">{profile.name?.slice(0,1)?.toUpperCase()||'V'}</span>}</div>;
}
function MediaImage({reference,className,alt,onError}:{reference?:string;className:string;alt:string;onError?:()=>void}) {
  const id=reference?.startsWith('media:')?reference.slice(6):'';
  const media=useGetProfileMedia(id,{query:{enabled:!!id,queryKey:getGetProfileMediaQueryKey(id)}});
  const [objectUrl,setObjectUrl]=useState('');
  useEffect(()=>{if(!media.data)return;const url=URL.createObjectURL(media.data);setObjectUrl(url);return()=>URL.revokeObjectURL(url)},[media.data]);
  const src=id?objectUrl:mediaUrl(reference);
  return src?<img src={src} onError={onError} className={className} alt={alt}/>:null;
}
function Empty({ title, detail, action }: { title: string; detail: string; action?: ReactNode }) { return <div className="rounded-[24px] border border-dashed border-white/10 bg-white/[.02] px-6 py-14 text-center"><div className="mx-auto flex h-14 w-14 items-center justify-center rounded-2xl bg-accent text-primary"><Sparkles size={23}/></div><h3 className="mt-5 text-lg font-bold">{title}</h3><p className="mx-auto mt-2 max-w-md text-sm leading-6 text-muted-foreground">{detail}</p>{action&&<div className="mt-5">{action}</div>}</div>; }

function DiscoverPage() {
  const qc=useQueryClient(); const [index,setIndex]=useState(0); const [ageMin,setAgeMin]=useState(22); const [ageMax,setAgeMax]=useState(35); const [gender,setGender]=useState('Everyone'); const [city,setCity]=useState(''); const [filters,setFilters]=useState(false); const [detail,setDetail]=useState(false); const [notice,setNotice]=useState(''); const [lastPass,setLastPass]=useState<string|null>(null);
  const params=useMemo(()=>({ageMin,ageMax,gender,...(city.trim()?{city:city.trim()}:{})}),[ageMin,ageMax,gender,city]);
  const discover=useGetDiscoverProfiles(params,{query:{queryKey:getGetDiscoverProfilesQueryKey(params),refetchOnWindowFocus:false}});
  const profiles=discover.data??[]; const profile=profiles[index]; const reaction=useCreateReaction(); const undo=useUndoLastPass(); const likes=useGetDailyLikeStatus({query:{queryKey:getGetDailyLikeStatusQueryKey(),refetchInterval:60000}}); const superStatus=useGetSuperLikeStatus({query:{queryKey:getGetSuperLikeStatusQueryKey(),refetchInterval:60000}}); const boost=useGetBoostStatus({query:{queryKey:getGetBoostStatusQueryKey(),refetchInterval:10000}}); const activate=useActivateBoost(); const recordView=useRecordProfileView(); const block=useBlockProfile(); const report=useReportProfile(); const sentView=useRef(new Set<string>());
  useEffect(()=>{if(profile&&!profile.isDemo&&!sentView.current.has(profile.id)){sentView.current.add(profile.id);recordView.mutate({profileId:profile.id});}},[profile?.id]);
  async function act(type:'like'|'pass'|'super') {
    if(!profile)return;
    if(type==='like'&&likes.data?.remaining===0){setNotice('You have reached today’s like limit.');return}
    const current=profile; setIndex(v=>v+1); setNotice('');
    try {const result=await reaction.mutateAsync({data:{toUserId:current.id,type}}); setLastPass(type==='pass'?current.id:null); if(type==='like')void qc.invalidateQueries({queryKey:getGetDailyLikeStatusQueryKey()});if(type==='super')void qc.invalidateQueries({queryKey:getGetSuperLikeStatusQueryKey()});if(result.matched){await qc.invalidateQueries({queryKey:getGetMatchesQueryKey()});setNotice(`You and ${current.name} matched.`)}}
    catch{setIndex(v=>Math.max(0,v-1));setNotice('That swipe did not save. Try again.')}
  }
  async function blockCurrent(){if(!profile)return;if(!window.confirm(`Block ${profile.name}? You will no longer see each other or be able to chat.`))return;try{await block.mutateAsync({data:{targetUserId:profile.id}});setDetail(false);await qc.invalidateQueries({queryKey:getGetDiscoverProfilesQueryKey(params)});}catch{setNotice('Could not block this profile. Try again.')}}
  async function reportCurrent(reason:ReportInputReason){if(!profile)return;try{await report.mutateAsync({data:{targetUserId:profile.id,reason}});setNotice('Report received. Thank you for looking out for the community.');}catch{setNotice('Could not submit report. Try again.')}}
  if(discover.isLoading)return <PageFrame><PageHeading eyebrow="Discover" title="Finding your next spark"/><Busy/></PageFrame>;
  if(discover.isError)return <PageFrame><Retry onRetry={()=>void discover.refetch()} text="Discovery could not load right now."/></PageFrame>;
  if(!profile)return <PageFrame><PageHeading eyebrow="Discover" title="That's everyone for now" description="Try broadening your filters, or check back soon."/><Empty title="You’re all caught up" detail="Your next connection might be just outside your current filters." action={<button data-testid="button-open-filters-empty" onClick={()=>setFilters(true)} className="rounded-xl bg-primary px-4 py-2.5 font-bold text-[#24111b]">Adjust filters</button>}/></PageFrame>;
  return <PageFrame><PageHeading eyebrow="Discover / a little serendipity" title="Meet someone new" description={`${likes.data?.remaining??'—'} likes left today · ${superStatus.data?.remaining??'—'} super likes available`} action={<div className="flex gap-2"><button disabled={!boost.data?.available||activate.isPending} onClick={()=>activate.mutate(undefined,{onSuccess:()=>{void qc.invalidateQueries({queryKey:getGetBoostStatusQueryKey()});setNotice('Your boost is active for 30 minutes.')}})} data-testid="button-activate-boost" className="inline-flex items-center gap-2 rounded-xl border border-white/10 px-3 py-2.5 text-xs font-bold disabled:opacity-40"><Zap size={15} className="text-amber-300"/>Boost</button><button onClick={()=>setFilters(true)} data-testid="button-discovery-filters" className="rounded-xl border border-white/10 p-2.5"><SlidersHorizontal size={17}/></button></div>}/>
    {notice&&<div role="status" data-testid="status-discover" className="mb-4 rounded-xl border border-primary/20 bg-accent px-4 py-3 text-sm text-[#ffafd1]">{notice}<button onClick={()=>setNotice('')} data-testid="button-dismiss-notice" className="float-right"><X size={16}/></button></div>}
    <div className="grid gap-5 lg:grid-cols-[minmax(360px,530px)_1fr]">
      <article className="relative min-h-[540px] overflow-hidden rounded-[30px] border border-white/10 bg-[#25202a] shadow-xl md:min-h-[630px]" onTouchStart={(e)=>{(e.currentTarget as HTMLElement).dataset.touchX=String(e.touches[0].clientX)}} onTouchEnd={(e)=>{const x=Number((e.currentTarget as HTMLElement).dataset.touchX);const dx=e.changedTouches[0].clientX-x;if(Math.abs(dx)>90)void act(dx>0?'like':'pass')}} data-testid={`card-discover-${profile.id}`}>
        {profile.photos?.[0]&&<MediaImage reference={profile.photos[0]} className="absolute inset-0 h-full w-full object-cover" alt={`${profile.name}, ${profile.age}`}/>}
        {!profile.photos?.[0]&&<div className="absolute inset-0 bg-[radial-gradient(ellipse_at_50%_25%,#9f6076,#382b3a_55%,#1b1820)]"><div className="absolute left-[25%] top-[12%] h-[36%] w-[50%] rounded-[50%] bg-[linear-gradient(140deg,#d6a28c,#83515a)]"/><div className="absolute bottom-[-12%] left-[9%] h-[62%] w-[82%] rounded-t-[48%] bg-[linear-gradient(140deg,#d1b2a4,#745061)]"/></div>}
        <div className="absolute inset-0 bg-gradient-to-t from-[#130f16] via-[#17121a]/10 to-[#17121a]/20"/>
        {profile.superLikedYou&&<span className="absolute left-5 top-5 flex items-center gap-2 rounded-full bg-black/40 px-3 py-2 text-xs font-bold text-amber-200 backdrop-blur"><Star size={14}/>Super liked you</span>}
        <button onClick={()=>setDetail(!detail)} data-testid="button-profile-details" aria-label="Profile details" className="absolute inset-0 z-[1]"/>
        <div className="absolute inset-x-5 bottom-24 z-[2] pointer-events-none"><div className="flex items-end gap-2"><h2 className="text-4xl font-bold tracking-tight">{profile.name}</h2><span className="pb-1 text-2xl">{profile.age}</span></div><div className="mt-2 flex items-center gap-1.5 text-sm text-white/75"><MapPin size={14}/>{profile.city||'Nearby'}{profile.country?`, ${profile.country}`:''}</div><p className="mt-4 line-clamp-3 max-w-lg text-sm leading-6 text-white/85">{profile.bio}</p><div className="mt-3 flex flex-wrap gap-2">{profile.interests?.slice(0,4).map(i=><span key={i} className="rounded-full border border-white/20 bg-black/20 px-3 py-1 text-xs backdrop-blur">{i}</span>)}</div></div>
        <div className="absolute inset-x-0 bottom-0 z-[3] flex items-center justify-center gap-4 bg-gradient-to-t from-[#141117] via-[#141117]/80 to-transparent px-4 pb-5 pt-9">
          <button onClick={()=>void act('pass')} disabled={reaction.isPending} data-testid="button-pass-profile" className="flex h-12 w-12 items-center justify-center rounded-full border border-white/15 bg-[#28232d] text-muted-foreground hover:text-foreground"><X size={23}/></button>
          <button onClick={()=>{if(lastPass)undo.mutate(undefined,{onSuccess:async r=>{if(r.undone){setIndex(v=>Math.max(0,v-1));setLastPass(null);await qc.invalidateQueries({queryKey:getGetDiscoverProfilesQueryKey(params)})}}})}} disabled={!lastPass||undo.isPending} data-testid="button-undo-pass" className="flex h-10 w-10 items-center justify-center rounded-full border border-white/10 bg-[#28232d] text-muted-foreground disabled:opacity-40"><ArrowLeft size={17}/></button>
          <button onClick={()=>void act('super')} disabled={reaction.isPending||superStatus.data?.remaining===0} data-testid="button-super-like" className="flex h-12 w-12 items-center justify-center rounded-full bg-[#f3c75c] text-[#211a11] shadow-lg disabled:opacity-40"><Star size={21}/></button>
          <button onClick={()=>void act('like')} disabled={reaction.isPending||likes.data?.remaining===0} data-testid="button-like-profile" className="flex h-14 w-14 items-center justify-center rounded-full bg-primary text-[#27101d] shadow-[0_8px_30px_rgba(243,78,154,.32)] disabled:opacity-40"><Heart size={25} fill="currentColor"/></button>
        </div>
      </article>
      <aside className="hidden rounded-[28px] border border-white/[.08] bg-card p-7 lg:block">
        <div className="text-xs font-bold uppercase tracking-[.18em] text-primary">Your discovery</div><h3 className="brand mt-3 text-2xl font-bold">Curiosity looks good on you.</h3><p className="mt-3 text-sm leading-6 text-muted-foreground">Take a moment with the full profile. The best conversations often begin with one good detail.</p>
        <div className="mt-7 space-y-4 border-t border-white/[.08] pt-5 text-sm"><div className="flex justify-between"><span className="text-muted-foreground">Likes remaining</span><strong>{likes.data?.remaining??'—'}</strong></div><div className="flex justify-between"><span className="text-muted-foreground">Super likes</span><strong>{superStatus.data?.remaining??'—'}</strong></div><div className="flex justify-between"><span className="text-muted-foreground">Boost</span><strong>{boost.data?.active?'Active':boost.data?.available?'Ready':'Cooling down'}</strong></div></div>
        <button onClick={()=>setDetail(true)} data-testid="button-open-full-profile" className="mt-7 inline-flex items-center gap-2 rounded-xl bg-secondary px-4 py-3 text-sm font-bold">Read {profile.name}’s profile <ArrowRight size={15}/></button>
        <div className="mt-7 rounded-2xl border border-white/[.08] bg-white/[.025] p-4 text-xs leading-5 text-muted-foreground"><div className="mb-2 flex items-center gap-2 font-bold text-foreground"><Shield size={14} className="text-[#8ed9b7]"/>Your safety is in your hands</div>Block or report any profile that crosses your boundaries.</div>
      </aside>
    </div>
    {detail&&<Dialog title={`${profile.name}, ${profile.age}`} onClose={()=>setDetail(false)}><div className="space-y-4"><p className="text-sm text-muted-foreground">{profile.city} · {profile.gender} · Looking for {profile.lookingFor}</p><p className="whitespace-pre-wrap text-sm leading-6">{profile.bio||'No bio added yet.'}</p><div className="flex flex-wrap gap-2">{profile.interests?.map(i=><span key={i} className="rounded-full bg-accent px-3 py-1.5 text-xs text-[#ffafd1]">{i}</span>)}</div><div className="grid grid-cols-2 gap-2 pt-2"><button onClick={()=>void reportCurrent('inappropriate')} data-testid="button-report-profile" className="rounded-xl border border-white/10 px-4 py-3 text-sm font-semibold">Report</button><button onClick={()=>void blockCurrent()} data-testid="button-block-profile" className="rounded-xl border border-rose-400/20 px-4 py-3 text-sm font-semibold text-rose-300">Block profile</button></div></div></Dialog>}
    {filters&&<Dialog title="Discovery filters" onClose={()=>setFilters(false)}><div className="space-y-5"><div className="grid grid-cols-2 gap-3"><label className="text-xs text-muted-foreground">Age from<input data-testid="input-filter-age-min" type="number" min="18" value={ageMin} onChange={e=>setAgeMin(Number(e.target.value))} className="field mt-2"/></label><label className="text-xs text-muted-foreground">Age to<input data-testid="input-filter-age-max" type="number" min={ageMin} value={ageMax} onChange={e=>setAgeMax(Number(e.target.value))} className="field mt-2"/></label></div><label className="block text-xs text-muted-foreground">Interested in<select data-testid="select-filter-gender" value={gender} onChange={e=>setGender(e.target.value)} className="field mt-2"><option>Everyone</option><option>Woman</option><option>Man</option><option>Non-binary</option></select></label><label className="block text-xs text-muted-foreground">City<input data-testid="input-filter-city" value={city} onChange={e=>setCity(e.target.value)} placeholder="Any city" className="field mt-2"/></label><button onClick={()=>{setIndex(0);setFilters(false)}} data-testid="button-apply-filters" className="w-full rounded-xl bg-primary py-3 font-bold text-[#27101d]">Show people</button></div></Dialog>}
  </PageFrame>;
}
function Dialog({ title, children, onClose }: { title:string; children:ReactNode; onClose:()=>void }) { return <div className="fixed inset-0 z-50 flex items-end justify-center bg-black/65 p-0 backdrop-blur-sm sm:items-center sm:p-5" role="presentation" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><section className="max-h-[90dvh] w-full max-w-lg overflow-y-auto rounded-t-[26px] border border-white/10 bg-[#211d25] p-5 shadow-2xl sm:rounded-[26px] sm:p-7"><div className="mb-6 flex items-center justify-between"><h2 className="brand text-2xl font-bold">{title}</h2><button onClick={onClose} data-testid="button-close-dialog" aria-label="Close" className="rounded-lg p-2 text-muted-foreground hover:bg-white/5"><X size={19}/></button></div>{children}</section></div>; }

function MatchesPage() {
  const qc=useQueryClient(); const matches=useGetMatches({query:{refetchInterval:15000}}); const blocked=useGetBlockedProfiles(); const prompts=useGetIcebreakers(); const send=useSendMessage(); const block=useBlockProfile(); const unblock=useUnblockProfile(); const report=useReportProfile(); const del=useDeleteChat(); const unmatch=useUnmatchMatch(); const [target,setTarget]=useState<Profile|null>(null);
  const refresh=async()=>Promise.all([qc.invalidateQueries({queryKey:getGetMatchesQueryKey()}),qc.invalidateQueries({queryKey:getGetBlockedProfilesQueryKey()})]);
  async function safety(action:'block'|'unblock'|'report',p:Profile){try{if(action==='block')await block.mutateAsync({data:{targetUserId:p.id}});if(action==='unblock')await unblock.mutateAsync({targetUserId:p.id});if(action==='report')await report.mutateAsync({data:{targetUserId:p.id,reason:'other'}});setTarget(null);await refresh()}catch{window.alert(`Could not ${action} this profile. Try again.`)}}
  async function opener(matchId:string, content:string){try{await send.mutateAsync({matchId,data:{content}});await refresh()}catch{window.alert('Could not send that opener.')}}
  async function removeChat(id:string,kind:'delete'|'unmatch'){const msg=kind==='delete'?'Hide this conversation for you only?':'Unmatch? This removes the match and shared chat for both of you.';if(!window.confirm(msg))return;try{if(kind==='delete')await del.mutateAsync({matchId:id});else await unmatch.mutateAsync({matchId:id});await refresh()}catch{window.alert('That action could not be completed.')}}
  return <PageFrame><PageHeading eyebrow="Your connections" title="Matches" description="A mutual like is a good place to begin. Only matches can message each other."/>
    {matches.isLoading?<Busy/>:matches.isError?<Retry onRetry={()=>void matches.refetch()}/>:!matches.data?.length?<Empty title="Your first match is out there" detail="When you both like each other, you can start a conversation." action={<Link href="/discover" data-testid="link-discover-empty" className="rounded-xl bg-primary px-4 py-2.5 font-bold text-[#26111b]">Explore profiles</Link>}/>:<div className="grid gap-3 md:grid-cols-2">{matches.data.map(m=><article key={m.id} data-testid={`card-match-${m.id}`} className="rounded-[22px] border border-white/[.08] bg-card p-4 transition-colors hover:border-white/[.14]"><div className="flex items-start gap-3"><Link href={`/chat/${m.id}`} data-testid={`link-match-chat-${m.id}`} className={`flex min-w-0 flex-1 items-center gap-3 ${m.blockedByMe||m.blockedMe?'pointer-events-none opacity-60':''}`}><Avatar profile={m.profile}/><div className="min-w-0 flex-1"><div className="font-bold">{m.profile.name}, {m.profile.age}</div><div className={`mt-1 truncate text-xs ${m.blockedByMe||m.blockedMe?'text-rose-300':'text-muted-foreground'}`}>{m.blockedByMe?'Blocked by you':m.blockedMe?'This person blocked you':m.lastMessage||'Say hello and start a conversation'}</div></div><MessageCircle size={18} className="text-primary"/></Link><button onClick={()=>setTarget(m.profile)} data-testid={`button-match-actions-${m.id}`} className="rounded-lg p-2 text-muted-foreground hover:bg-white/5"><MoreHorizontal size={19}/></button></div>
      {!m.blockedByMe&&!m.blockedMe&&!m.lastMessage&&prompts.data&&prompts.data.length>0&&<div className="mt-4 border-t border-white/[.07] pt-3"><p className="mb-2 text-[10px] font-bold uppercase tracking-[.14em] text-muted-foreground">Start with an icebreaker</p><button disabled={send.isPending} onClick={()=>void opener(m.id,prompts.data[0].question)} data-testid={`button-icebreaker-${m.id}`} className="flex w-full items-center justify-between gap-3 rounded-xl bg-white/[.035] p-3 text-left text-xs leading-5 hover:bg-white/[.06]"><span>{prompts.data[0].question}</span><ArrowRight size={14} className="shrink-0 text-primary"/></button></div>}
    </article>)}</div>}
    <section className="mt-12"><PageHeading eyebrow="Your boundaries" title="Blocked profiles" description="Blocking and unmatching are different. Block prevents future contact; unmatch ends the shared connection."/>
    {blocked.isLoading?<div className="h-20 animate-pulse rounded-2xl bg-white/[.04]"/>:blocked.isError?<Retry onRetry={()=>void blocked.refetch()}/>:!blocked.data?.length?<div className="rounded-2xl border border-white/[.08] px-5 py-5 text-sm text-muted-foreground">Profiles you block will appear here.</div>:<div className="space-y-2">{blocked.data.map(b=><div key={b.profile.id} className="flex items-center gap-3 rounded-2xl border border-white/[.08] bg-card p-3"><Avatar profile={b.profile} size="sm"/><div className="flex-1"><div className="text-sm font-bold">{b.profile.name}</div><div className="text-xs text-rose-300">Blocked</div></div><button onClick={()=>void safety('unblock',b.profile)} data-testid={`button-unblock-${b.profile.id}`} className="rounded-lg border border-white/10 px-3 py-2 text-xs font-bold">Unblock</button><button onClick={()=>setTarget(b.profile)} data-testid={`button-blocked-actions-${b.profile.id}`} className="p-2 text-muted-foreground"><MoreHorizontal size={18}/></button></div>)}</div>}</section>
    {target&&<Dialog title={target.name} onClose={()=>setTarget(null)}><div className="space-y-2"><button onClick={()=>void safety('report',target)} data-testid="button-report-from-match" className="w-full rounded-xl border border-white/10 p-3 text-left text-sm">Report profile</button><button onClick={()=>void safety('block',target)} data-testid="button-block-from-match" className="w-full rounded-xl border border-rose-400/20 p-3 text-left text-sm text-rose-300">Block profile</button>{matches.data?.find(m=>m.profile.id===target.id)&&<><button onClick={()=>void removeChat(matches.data!.find(m=>m.profile.id===target.id)!.id,'delete')} data-testid="button-delete-chat" className="w-full rounded-xl border border-white/10 p-3 text-left text-sm">Delete chat for me</button><button onClick={()=>void removeChat(matches.data!.find(m=>m.profile.id===target.id)!.id,'unmatch')} data-testid="button-unmatch" className="w-full rounded-xl border border-rose-400/20 p-3 text-left text-sm text-rose-300">Unmatch both of you</button></>}</div></Dialog>}
  </PageFrame>;
}

function ChatPage({matchId}:{matchId:string}) {
  const qc=useQueryClient(); const profile=useGetMyProfile(); const matches=useGetMatches({query:{refetchInterval:12000}}); const match=matches.data?.find(m=>m.id===matchId); const blocked=!!match?.blockedByMe||!!match?.blockedMe;
  const msgs=useGetMessages(matchId,{query:{enabled:!!match,queryKey:getGetMessagesQueryKey(matchId),refetchInterval:10000}}); const typing=useGetTypingStatus(matchId,{query:{enabled:!!match,queryKey:['/api/vibeswipe/matches',matchId,'typing'],refetchInterval:3500}}); const receipt=useGetChatReadReceipt(matchId,{query:{enabled:!!match,queryKey:getGetChatReadReceiptQueryKey(matchId),refetchInterval:5000}}); const presence=useGetMatchPresence(matchId,{query:{enabled:!!match,queryKey:getGetMatchPresenceQueryKey(matchId),refetchInterval:15000}}); const heartbeat=useHeartbeatPresence();
  const ice=useGetIcebreakers({query:{enabled:!!match,queryKey:['/api/vibeswipe/icebreakers']}}); const send=useSendMessage(); const updateTyping=useUpdateTypingStatus(); const markRead=useMarkChatRead(); const del=useDeleteMessage(); const clear=useClearChat(); const unmatch=useUnmatchMatch(); const block=useBlockProfile(); const unblock=useUnblockProfile(); const report=useReportProfile(); const theme=useUpdateChatTheme(); const upload=useRequestChatMediaUpload(); const transcode=useTranscodeProfileVideo(); const [draft,setDraft]=useState(''); const [error,setError]=useState(''); const [actions,setActions]=useState(false); const [themeOpen,setThemeOpen]=useState(false); const [deleteTarget,setDeleteTarget]=useState<Message|null>(null); const [busy,setBusy]=useState(false); const bottom=useRef<HTMLDivElement>(null);
  const messages=(msgs.data??[]).slice().reverse(); const last=messages[messages.length-1];
  useEffect(()=>{if(last&&last.senderId!==profile.data?.id&&!last.isRead)markRead.mutate({matchId});},[last?.id,profile.data?.id]);
  useEffect(()=>{heartbeat.mutate({data:{isActive:true}});const beat=window.setInterval(()=>heartbeat.mutate({data:{isActive:document.visibilityState==='visible'}}),30000);const visibility=()=>heartbeat.mutate({data:{isActive:document.visibilityState==='visible'}});document.addEventListener('visibilitychange',visibility);return()=>{clearInterval(beat);document.removeEventListener('visibilitychange',visibility)}},[]);
  useEffect(()=>{if(blocked)return;const t=setTimeout(()=>updateTyping.mutate({matchId,data:{isTyping:!!draft.trim()}}),300);return()=>clearTimeout(t)},[draft,blocked,matchId]);
  useEffect(()=>{bottom.current?.scrollIntoView({behavior:'smooth'})},[messages.length]);
  if(matches.isLoading||msgs.isLoading)return <PageFrame><div className="h-16 animate-pulse rounded-2xl bg-white/[.04]"/><div className="mt-6"><Busy/></div></PageFrame>;
  if(!match)return <PageFrame><Empty title="Conversation unavailable" detail="This chat may have ended or the match is no longer available." action={<Link href="/matches" data-testid="link-back-matches" className="rounded-xl bg-secondary px-4 py-2.5 font-bold">Back to matches</Link>}/></PageFrame>;
  async function sendMessage(content:string, media?:{mediaReference:string;mediaType:'image'|'video'|'audio'}){if(blocked||(!content.trim()&&!media)||send.isPending)return;const old=draft;setDraft('');try{await send.mutateAsync({matchId,data:{content:content.trim(),...media}});updateTyping.mutate({matchId,data:{isTyping:false}});void qc.invalidateQueries({queryKey:getGetMessagesQueryKey(matchId)});void qc.invalidateQueries({queryKey:getGetMatchesQueryKey()});setError('')}catch{setDraft(old);setError('Message could not be sent. Please try again.')}}
  async function deleteMessageFor(message:Message,forEveryone:boolean){try{await del.mutateAsync({matchId,messageId:message.id,data:{forEveryone}});if(!forEveryone)qc.setQueryData<Message[]>(getGetMessagesQueryKey(matchId),current=>(current??[]).filter(item=>item.id!==message.id));await msgs.refetch()}catch{setError('Message could not be deleted. Please try again.')}finally{setDeleteTarget(null)}}
  async function attach(file?:File){if(!file)return;const kind=file.type.startsWith('video/')?'video':file.type.startsWith('audio/')?'audio':'image';if(kind==='image'&&file.size>15*1024*1024){setError('Choose an image smaller than 15 MB.');return}if(kind==='video'&&file.size>500*1024*1024){setError('Choose a video smaller than 500 MB.');return}if(kind==='audio'&&file.size>25*1024*1024){setError('Choose an audio note smaller than 25 MB.');return}setBusy(true);setError('');try{const allowed:MediaUploadInputContentType[]=['image/jpeg','image/png','image/webp','image/heic','video/mp4','video/quicktime','audio/mp4','audio/m4a','audio/aac','audio/wav'];const fallback:MediaUploadInputContentType=kind==='image'?'image/jpeg':kind==='video'?'video/mp4':'audio/m4a';const contentType:MediaUploadInputContentType=allowed.includes(file.type as MediaUploadInputContentType)?file.type as MediaUploadInputContentType:fallback;const signed=await upload.mutateAsync({matchId,data:{name:file.name,size:file.size,contentType,mediaType:kind}});const res=await fetch(signed.uploadURL,{method:'PUT',headers:{'Content-Type':contentType},body:file});if(!res.ok)throw new Error('Upload did not complete.');const mediaReference=kind==='video'?(await transcode.mutateAsync({mediaId:signed.mediaId})).mediaReference:signed.mediaReference;await sendMessage('',{mediaReference,mediaType:kind})}catch(e){setError(e instanceof Error?e.message:'Attachment could not be uploaded.')}finally{setBusy(false)}}
  async function action(a:string){if(!match)return;setActions(false);try{if(a==='block'){if(match.blockedByMe)await unblock.mutateAsync({targetUserId:match.profile.id});else if(window.confirm(`Block ${match.profile.name}?`))await block.mutateAsync({data:{targetUserId:match.profile.id}})}if(a==='report')await report.mutateAsync({data:{targetUserId:match.profile.id,reason:'other'}});if(a==='clear'){if(window.confirm('Clear messages from your view?')){await clear.mutateAsync({matchId});await qc.invalidateQueries({queryKey:getGetMessagesQueryKey(matchId)})}}if(a==='unmatch'){if(window.confirm('Unmatch and remove this shared chat?')){await unmatch.mutateAsync({matchId});void qc.invalidateQueries({queryKey:getGetMatchesQueryKey()})}}if(a==='theme')setThemeOpen(true)}catch{setError('That action did not complete. Please try again.')}}
  return <div className="mx-auto flex h-[calc(100dvh-66px)] max-w-[1120px] flex-col px-3 py-3 md:h-[100dvh] md:px-7 md:py-6">
    <header className="flex items-center gap-3 border-b border-white/[.08] pb-4"><Link href="/matches" data-testid="link-chat-back" className="rounded-xl p-2 text-muted-foreground hover:bg-white/[.05]"><ArrowLeft size={19}/></Link><Avatar profile={match.profile} size="sm"/><div className="min-w-0 flex-1"><div className="font-bold">{match.profile.name}</div><div className="text-xs text-muted-foreground">{presence.data?.isOnline?<span className="text-emerald-300">Online</span>:presence.data?.lastSeenAt?`Last seen ${new Date(presence.data.lastSeenAt).toLocaleString()}`:'A conversation just for your mutual match'}</div></div><button onClick={()=>setActions(true)} data-testid="button-chat-actions" className="rounded-xl p-2 text-muted-foreground"><MoreHorizontal size={20}/></button></header>
    {blocked&&<div className="mt-3 rounded-xl border border-rose-300/15 bg-rose-300/[.06] px-4 py-3 text-sm text-rose-200">Messaging is unavailable while this profile is blocked.</div>}
    {msgs.isError&&<button onClick={()=>void msgs.refetch()} data-testid="button-retry-messages" className="mt-2 rounded-lg bg-rose-300/10 p-2 text-xs text-rose-200">Messages failed to load. Tap to retry.</button>}
    <div className="hide-scrollbar flex-1 space-y-3 overflow-y-auto py-5">{!messages.length&&<div className="mx-auto max-w-sm py-10 text-center"><div className="mx-auto flex h-12 w-12 items-center justify-center rounded-2xl bg-accent text-primary"><MessageCircle size={22}/></div><h2 className="mt-4 font-bold">A good conversation starts here</h2><p className="mt-2 text-xs text-muted-foreground">A mutual match is an open door. Make the first message yours.</p><div className="mt-5 space-y-2">{ice.data?.slice(0,3).map(i=><button key={i.id} disabled={blocked||send.isPending} onClick={()=>void sendMessage(i.question)} data-testid={`button-chat-icebreaker-${i.id}`} className="w-full rounded-xl border border-white/10 bg-white/[.025] p-3 text-left text-xs hover:bg-white/[.05]">{i.question}</button>)}</div></div>}
      {messages.map(m=><div key={m.id} className={`group flex ${m.senderId===profile.data?.id?'justify-end':'justify-start'}`} data-testid={`message-${m.id}`}><div className={`max-w-[82%] rounded-2xl px-4 py-3 text-sm leading-6 md:max-w-[65%] ${m.senderId===profile.data?.id?'bg-primary text-[#28111e]':'border border-white/[.08] bg-card'}`}>{m.deletedForEveryone?<span className="italic opacity-60">This message was deleted.</span>:<>{m.mediaReference&&m.mediaType!=='audio'&&<img src={mediaUrl(m.mediaReference)} alt="Message attachment" className="mb-2 max-h-72 rounded-xl object-cover"/>}{m.mediaType==='audio'&&<audio controls src={mediaUrl(m.mediaReference)} className="max-w-full"/>}{m.content}</>}<div className="mt-1 flex items-center justify-end gap-2 text-[10px] opacity-60">{new Date(m.createdAt).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'})}{m.senderId===profile.data?.id&&m.isRead&&<span>Read</span>}<button onClick={async()=>{if(window.confirm('Delete this message for you?')){await del.mutateAsync({matchId,messageId:m.id,data:{forEveryone:false}});void msgs.refetch()}}} data-testid={`button-delete-message-${m.id}`} className="hidden group-hover:inline">Delete</button></div></div></div>)}
      {typing.data?.isTyping&&<div className="text-xs text-muted-foreground">{match.profile.name} is typing</div>}<div ref={bottom}/></div>
    {receipt.data?.readAt&&<div className="pb-2 text-right text-[10px] text-muted-foreground">Seen {new Date(receipt.data.readAt).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'})}</div>}
    {error&&<div role="alert" className="pb-2 text-xs text-rose-300">{error}</div>}
    <form onSubmit={e=>{e.preventDefault();void sendMessage(draft)}} className="flex items-end gap-2 border-t border-white/[.08] pt-3"><label className="flex h-11 w-11 shrink-0 cursor-pointer items-center justify-center rounded-xl border border-white/10 text-muted-foreground hover:bg-white/[.04]" aria-label="Attach photo, video, or voice note"><ImagePlus size={18}/><input data-testid="input-chat-media" type="file" accept="image/*,video/mp4,video/quicktime,audio/*" className="hidden" disabled={blocked||busy} onChange={e=>{void attach(e.currentTarget.files?.[0]);e.currentTarget.value=''}}/></label><textarea data-testid="input-chat-message" value={draft} onChange={e=>setDraft(e.target.value)} disabled={blocked} maxLength={2000} rows={1} placeholder={blocked?'Messaging unavailable':'Write a message'} className="field min-h-11 max-h-32 flex-1 resize-y py-3"/><button disabled={blocked||busy||send.isPending||(!draft.trim()&&!busy)} data-testid="button-send-message" className="h-11 rounded-xl bg-primary px-4 font-bold text-[#28111e] disabled:opacity-40">{busy?'Uploading':'Send'}</button></form>
    {actions&&<Dialog title="Conversation settings" onClose={()=>setActions(false)}><div className="space-y-2"><button onClick={()=>void action('theme')} data-testid="button-change-chat-theme" className="w-full rounded-xl border border-white/10 p-3 text-left text-sm">Change chat color</button><button onClick={()=>void action('clear')} data-testid="button-clear-chat" className="w-full rounded-xl border border-white/10 p-3 text-left text-sm">Clear chat for me</button><button onClick={()=>void action('report')} data-testid="button-report-chat-profile" className="w-full rounded-xl border border-white/10 p-3 text-left text-sm">Report profile</button><button onClick={()=>void action('block')} data-testid="button-block-chat-profile" className="w-full rounded-xl border border-rose-300/20 p-3 text-left text-sm text-rose-300">{match.blockedByMe?'Unblock profile':'Block profile'}</button><button onClick={()=>void action('unmatch')} data-testid="button-chat-unmatch" className="w-full rounded-xl border border-rose-300/20 p-3 text-left text-sm text-rose-300">Unmatch</button></div></Dialog>}
    {themeOpen&&<Dialog title="Choose a chat color" onClose={()=>setThemeOpen(false)}><div className="grid grid-cols-2 gap-2">{(['pink','blue','purple','green','dark','light'] as ChatTheme[]).map(t=><button key={t} onClick={()=>theme.mutate({matchId,data:{theme:t}},{onSuccess:()=>{setThemeOpen(false);void qc.invalidateQueries({queryKey:getGetMatchesQueryKey()})}})} data-testid={`button-theme-${t}`} className="rounded-xl border border-white/10 p-3 text-sm font-semibold capitalize">{t}</button>)}</div></Dialog>}
  </div>;
}

function ViewsPage(){const q=useGetWhoViewedYou({query:{queryKey:getGetWhoViewedYouQueryKey(),refetchInterval:30000}});return <PageFrame><PageHeading eyebrow="Your profile" title="Who viewed you" description="People who took a closer look."/>{q.isLoading?<Busy/>:q.isError?<Retry onRetry={()=>void q.refetch()}/>:!q.data?.length?<Empty title="No views yet" detail="When someone opens your profile, they’ll appear here."/>:<div className="space-y-2">{q.data.map(v=><Link key={`${v.profile.id}-${v.viewedAt}`} href={`/profile/${v.profile.id}`} data-testid={`link-viewer-${v.profile.id}`} className="flex items-center gap-4 rounded-2xl border border-white/[.08] bg-card p-4 hover:bg-white/[.04]"><Avatar profile={v.profile}/><div className="flex-1"><div className="font-bold">{v.profile.name}, {v.profile.age}</div><div className="mt-1 text-xs text-muted-foreground">{v.profile.city||'Nearby'} · {new Date(v.viewedAt).toLocaleString()}</div></div><ChevronRight size={18} className="text-muted-foreground"/></Link>)}</div>}</PageFrame>}
function NotificationsPage(){const qc=useQueryClient();const [,setLocation]=useLocation();const q=useGetNotifications({query:{queryKey:getGetNotificationsQueryKey(),refetchInterval:15000}});const mark=useMarkNotificationRead();async function open(n:any){if(!n.readAt)try{await mark.mutateAsync({notificationId:n.id});void qc.invalidateQueries({queryKey:getGetNotificationsQueryKey()})}catch{} if(n.matchId&&(n.type==='new_match'||n.type==='new_message'))setLocation(`/chat/${n.matchId}`);else if(n.type==='new_match')setLocation('/matches');else setLocation(`/profile/${n.actor.id}`)}
const title=(n:any)=>n.type==='new_match'?`You matched with ${n.actor.name}`:n.type==='new_message'?`${n.actor.name} sent you a message`:n.type==='new_like'?`${n.actor.name} liked you`:`${n.actor.name} viewed your profile`;
return <PageFrame><PageHeading eyebrow="Your activity" title="Notifications" description={q.data?`${Object.values(q.data.unreadCounts??{}).reduce((a:any,b:any)=>a+b,0)} unread updates`:''}/>{q.isLoading?<Busy/>:q.isError?<Retry onRetry={()=>void q.refetch()}/>:!q.data?.notifications.length?<Empty title="All caught up" detail="Your new matches, likes, messages, and profile views will show up here."/>:<div className="space-y-2">{q.data.notifications.map(n=><button key={n.id} onClick={()=>void open(n)} data-testid={`button-notification-${n.id}`} className={`flex w-full items-center gap-4 rounded-2xl border p-4 text-left ${n.readAt?'border-white/[.07] bg-card':'border-primary/20 bg-primary/[.055]'}`}><Avatar profile={n.actor}/><div className="min-w-0 flex-1"><div className="text-sm font-semibold">{title(n)}</div><div className="mt-1 text-xs text-muted-foreground">{new Date(n.createdAt).toLocaleString()}</div></div>{!n.readAt&&<span className="h-2 w-2 rounded-full bg-primary"/>}</button>)}</div>}</PageFrame>}

const emptyProfile:ProfileInput={name:'',age:18,gender:'',lookingFor:'Everyone',bio:'',city:'',country:null,state:null,interests:[],photos:[],videoUrl:null,preferences:{ageMin:22,ageMax:35,gender:'Everyone',distanceKm:50}};
function ProfilePage(){const q=useGetMyProfile();const settings=useGetVibeSwipeSettings();const [edit,setEdit]=useState(false);const save=useSaveMyProfile();const requestUpload=useRequestProfileMediaUpload();const transcode=useTranscodeProfileVideo();const [uploading,setUploading]=useState(false);const qc=useQueryClient();const [form,setForm]=useState<ProfileInput>(emptyProfile);useEffect(()=>{if(q.data)setForm({...q.data,preferences:q.data.preferences,interests:q.data.interests??[],photos:q.data.photos??[]})},[q.data]);const change=(key:keyof ProfileInput,value:any)=>setForm(v=>({...v,[key]:value}));
async function uploadProfileMedia(file?:File){if(!file)return;const video=file.type.startsWith('video/');const allowed:MediaUploadInputContentType[]=['image/jpeg','image/png','image/webp','image/heic','video/mp4','video/quicktime'];const contentType:MediaUploadInputContentType=allowed.includes(file.type as MediaUploadInputContentType)?file.type as MediaUploadInputContentType:(video?'video/mp4':'image/jpeg');setUploading(true);try{const result=await requestUpload.mutateAsync({data:{name:file.name,size:file.size,contentType,mediaType:video?'video':'image'}});const uploaded=await fetch(result.uploadURL,{method:'PUT',headers:{'Content-Type':contentType},body:file});if(!uploaded.ok)throw new Error('Upload could not be completed.');if(video){const done=await transcode.mutateAsync({mediaId:result.mediaId});change('videoUrl',done.mediaReference)}else change('photos',[...form.photos,result.mediaReference].slice(0,6))}catch{window.alert('Media could not be uploaded. Please try again.')}finally{setUploading(false)}}
async function submit(e:React.FormEvent){e.preventDefault();try{await save.mutateAsync({data:form});await qc.invalidateQueries({queryKey:getGetMyProfileQueryKey()});setEdit(false)}catch{window.alert('Profile could not be saved. Please try again.')}}
return <PageFrame><PageHeading eyebrow="You, in your own words" title="Your profile" description="The details that help a good conversation find its way." action={<Link href="/settings" data-testid="link-profile-settings" className="rounded-xl border border-white/10 p-3"><Settings size={17}/></Link>}/>{q.isLoading?<Busy/>:q.isError?<Retry onRetry={()=>void q.refetch()}/>:!q.data?<Empty title="Your profile is waiting" detail="Finish a few details to begin discovering people." action={<Link href="/onboarding" data-testid="link-profile-onboarding" className="rounded-xl bg-primary px-4 py-3 font-bold text-[#26111b]">Set up profile</Link>}/>:<><section className="rounded-[28px] border border-white/[.08] bg-card p-6 md:p-8"><div className="flex flex-col items-center gap-5 sm:flex-row"><Avatar profile={q.data} size="lg"/><div className="flex-1 text-center sm:text-left"><h2 className="text-2xl font-bold">{q.data.name}, {q.data.age}</h2><p className="mt-1 text-sm text-muted-foreground">{[q.data.city,q.data.state,q.data.country].filter(Boolean).join(', ')} · {q.data.gender}</p>{settings.data?.travelMode&&settings.data.travelCity&&<div className="mt-3 inline-flex items-center gap-1.5 rounded-full bg-accent px-3 py-1.5 text-xs font-semibold text-[#ffafd1]"><Navigation size={13}/>Traveling in {settings.data.travelCity}</div>}</div><button onClick={()=>setEdit(!edit)} data-testid="button-edit-profile" className="rounded-xl bg-primary px-4 py-3 text-sm font-bold text-[#26111b]">{edit?'Close editor':'Edit profile'}</button></div></section>
{edit&&<form onSubmit={e=>void submit(e)} className="mt-4 rounded-2xl border border-white/[.08] bg-card p-5 md:p-7"><h3 className="mb-5 text-lg font-bold">Edit your details</h3><div className="grid gap-4 sm:grid-cols-2"><Field label="Name"><input data-testid="input-profile-name" required maxLength={60} value={form.name} onChange={e=>change('name',e.target.value)} className="field"/></Field><Field label="Age (18+)"><input data-testid="input-profile-age" required type="number" min="18" max="120" value={form.age} onChange={e=>change('age',Number(e.target.value))} className="field"/></Field><Field label="Gender"><input data-testid="input-profile-gender" value={form.gender} onChange={e=>change('gender',e.target.value)} className="field"/></Field><Field label="Looking for"><input data-testid="input-profile-looking" value={form.lookingFor} onChange={e=>change('lookingFor',e.target.value)} className="field"/></Field><Field label="City"><input data-testid="input-profile-city" value={form.city} onChange={e=>change('city',e.target.value)} className="field"/></Field><Field label="Interests (comma separated)"><input data-testid="input-profile-interests" value={form.interests.join(', ')} onChange={e=>change('interests',e.target.value.split(',').map(x=>x.trim()).filter(Boolean).slice(0,12))} className="field"/></Field><Field label="Bio"><textarea data-testid="input-profile-bio" maxLength={500} rows={4} value={form.bio} onChange={e=>change('bio',e.target.value)} className="field sm:col-span-2"/></Field><Field label="Add profile media"><input data-testid="input-profile-media" type="file" accept="image/*,video/mp4,video/quicktime" disabled={uploading||form.photos.length>=6} onChange={e=>{void uploadProfileMedia(e.currentTarget.files?.[0]);e.currentTarget.value=''}} className="field file:mr-3 file:rounded-lg file:border-0 file:bg-accent file:px-3 file:py-2 file:text-xs file:font-bold"/></Field><p className="text-xs text-muted-foreground sm:col-span-2">{uploading?'Uploading media…':`${form.photos.length}/6 photos${form.videoUrl?' · profile video ready':''}`}</p><button disabled={save.isPending||uploading} data-testid="button-save-profile" className="rounded-xl bg-primary px-5 py-3 font-bold text-[#26111b] disabled:opacity-50">{save.isPending?'Saving…':'Save profile'}</button></div></form>}
<section className="mt-8 grid gap-7 md:grid-cols-[1fr_.8fr]"><div><h3 className="mb-3 text-xs font-bold uppercase tracking-[.18em] text-muted-foreground">A little about me</h3><p className="whitespace-pre-wrap text-sm leading-7">{q.data.bio||'Add a bio so people can get to know you.'}</p><h3 className="mb-3 mt-7 text-xs font-bold uppercase tracking-[.18em] text-muted-foreground">Things I’m into</h3><div className="flex flex-wrap gap-2">{q.data.interests.map(i=><span key={i} className="rounded-full bg-accent px-3.5 py-2 text-xs font-semibold text-[#ffafd1]">{i}</span>)}</div></div><div><h3 className="mb-3 text-xs font-bold uppercase tracking-[.18em] text-muted-foreground">Photos</h3><div className="grid grid-cols-3 gap-2">{q.data.photos.map((p,i)=><MediaImage key={`${p}-${i}`} reference={p} alt={`Profile photo ${i+1}`} className="aspect-[.8] w-full rounded-xl object-cover"/>)}</div></div></section></>}</PageFrame>}
function Field({label,children}:{label:string;children:ReactNode}){return <label className="grid gap-2 text-xs font-semibold text-muted-foreground">{label}{children}</label>}

const setupSteps=['First name','Last name','Age','Gender','Looking for','Profile photo','Bio','Country','State / region','City','Interests','Preferences'];
function OnboardingPage(){const [,setLocation]=useLocation();const q=useGetOnboardingDraft({query:{queryKey:getGetOnboardingDraftQueryKey()}});const saveDraft=useSaveOnboardingDraft();const clearDraft=useClearOnboardingDraft();const saveProfile=useSaveMyProfile();const requestUpload=useRequestProfileMediaUpload();const qc=useQueryClient();const [uploading,setUploading]=useState(false);const [step,setStep]=useState(0);const [data,setData]=useState<Record<string,any>>({firstName:'',lastName:'',age:'',gender:'',lookingFor:'Everyone',photos:[],bio:'',country:'',state:'',city:'',interests:'',ageMin:'22',ageMax:'35',distanceKm:50});const [ready,setReady]=useState(false);const [error,setError]=useState('');const [saved,setSaved]=useState(false);const currentKey=useRef('');useEffect(()=>{if(q.isSuccess&&!ready){const d=q.data.data??{};setData(v=>({...v,...d}));setStep(Math.max(0,Math.min(11,(q.data.step||1)-1)));setReady(true);currentKey.current=`${q.data.step}:${JSON.stringify(d)}`}},[q.data,q.isSuccess,ready]);const update=(k:string,v:any)=>{setData(d=>({...d,[k]:v}));setSaved(false);setError('')};
async function uploadOnboardingPhoto(file?:File){if(!file)return;if(file.size>15*1024*1024){setError('Choose an image smaller than 15 MB.');return}const types:MediaUploadInputContentType[]=['image/jpeg','image/png','image/webp','image/heic'];const contentType:MediaUploadInputContentType=types.includes(file.type as MediaUploadInputContentType)?file.type as MediaUploadInputContentType:'image/jpeg';setUploading(true);try{const result=await requestUpload.mutateAsync({data:{name:file.name,size:file.size,contentType,mediaType:'image'}});const put=await fetch(result.uploadURL,{method:'PUT',headers:{'Content-Type':contentType},body:file});if(!put.ok)throw new Error();update('photos',[...data.photos,result.mediaReference].slice(0,6))}catch{setError('Photo upload did not complete. Try again.')}finally{setUploading(false)}}
useEffect(()=>{if(!ready)return;const key=`${step+1}:${JSON.stringify(data)}`;if(key===currentKey.current)return;const t=setTimeout(()=>saveDraft.mutate({data:{step:step+1,data}},{onSuccess:d=>{currentKey.current=`${d.step}:${JSON.stringify(data)}`;qc.setQueryData(getGetOnboardingDraftQueryKey(),d);setSaved(true)}}),650);return()=>clearTimeout(t)},[ready,step,data]);
function validate(){if(step===0&&!data.firstName.trim())return 'Add your first name to continue.';if(step===1&&!data.lastName.trim())return 'Add your last name to continue.';if(step===2&&(!Number.isInteger(Number(data.age))||Number(data.age)<18))return 'VibeSwipe is for adults 18 and over.';if((step===3||step===4)&&!data[step===3?'gender':'lookingFor'])return 'Choose an option to continue.';if(step===5&&!data.photos?.length)return 'Add a profile photo to continue.';if(step===11&&(Number(data.ageMin)<18||Number(data.ageMax)<Number(data.ageMin)))return 'Set a valid age range.';return ''}
async function next(){const message=validate();if(message){setError(message);return}try{await saveDraft.mutateAsync({data:{step:Math.min(step+2,12),data}});if(step<11){setStep(step+1);return}await saveProfile.mutateAsync({data:{name:`${data.firstName} ${data.lastName}`.trim(),age:Number(data.age),gender:data.gender,lookingFor:data.lookingFor,bio:data.bio||'',city:data.city||'',country:data.country||null,state:data.state||null,interests:String(data.interests||'').split(',').map((x:string)=>x.trim()).filter(Boolean).slice(0,12),photos:data.photos,videoUrl:null,preferences:{ageMin:Number(data.ageMin)||22,ageMax:Number(data.ageMax)||35,gender:data.lookingFor,distanceKm:Number(data.distanceKm)||50}}});await clearDraft.mutateAsync();await qc.invalidateQueries();setLocation('/discover',{replace:true})}catch{setError('Could not save your setup. Please try again.')}}
if(q.isLoading||!ready)return <PageFrame><PageHeading eyebrow="Your profile" title="Getting your space ready"/><Busy/></PageFrame>;
const choices=(values:string[],key:string)=> <div className="grid grid-cols-2 gap-2">{values.map(v=><button type="button" key={v} onClick={()=>update(key,v)} data-testid={`button-choice-${key}-${v.toLowerCase().replaceAll(' ','-')}`} className={`rounded-xl border p-3 text-sm font-semibold ${data[key]===v?'border-primary/50 bg-accent text-[#ffafd1]':'border-white/10 bg-white/[.02]'}`}>{v}</button>)}</div>;
return <PageFrame><div className="mx-auto max-w-2xl"><PageHeading eyebrow="A good start" title="Set up your profile" description="Twelve quick steps. Your progress saves as you go."/><div className="mb-8"><div className="flex justify-between text-[10px] font-bold uppercase tracking-[.15em] text-muted-foreground"><span>Step {step+1} of 12</span><span>{saved?'Saved':'Saving as you go'}</span></div><div className="mt-3 h-1.5 overflow-hidden rounded-full bg-white/10"><div className="h-full rounded-full bg-primary transition-all" style={{width:`${((step+1)/12)*100}%`}}/></div></div>
<div className="min-h-[360px] rounded-[25px] border border-white/[.08] bg-card p-5 md:p-8"><p className="text-xs font-bold uppercase tracking-[.18em] text-primary">{setupSteps[step]}</p><h2 className="brand mt-3 text-3xl font-bold tracking-[-.04em]">{['What should we call you?','And your last name?','How old are you?','How do you describe yourself?','Who would you like to meet?','Choose a profile photo.','What would you like people to know?','Where are you from?','State or region?','Which city feels like home?','What are you into?','Set your discovery preferences.'][step]}</h2><p className="mt-2 text-sm text-muted-foreground">VibeSwipe is a space for adults 18 and over.</p><div className="mt-7 max-w-lg">
{step===0&&<input autoFocus data-testid="input-onboarding-first-name" value={data.firstName} onChange={e=>update('firstName',e.target.value)} placeholder="First name" className="field"/>}
{step===1&&<input autoFocus data-testid="input-onboarding-last-name" value={data.lastName} onChange={e=>update('lastName',e.target.value)} placeholder="Last name" className="field"/>}
{step===2&&<input data-testid="input-onboarding-age" type="number" min="18" max="120" value={data.age} onChange={e=>update('age',e.target.value)} placeholder="Age" className="field max-w-40"/>}
{step===3&&choices(['Woman','Man','Non-binary','Another identity'],'gender')}
{step===4&&choices(['Everyone','Women','Men','Non-binary people'],'lookingFor')}
{step===5&&<div><div className="mb-3 grid grid-cols-3 gap-2">{(data.photos as string[]).map((p:string,i:number)=><div key={p} className="relative"><MediaImage reference={p} className="aspect-[.8] w-full rounded-xl object-cover" alt={`Your photo ${i+1}`}/><button onClick={()=>update('photos',data.photos.filter((x:string)=>x!==p))} data-testid={`button-remove-onboarding-photo-${i}`} className="absolute right-1 top-1 rounded-full bg-black/70 p-1"><X size={14}/></button></div>)}</div><p className="text-xs text-muted-foreground">Add a clear, recent photo so people can recognize you.</p><label className="mt-3 flex cursor-pointer items-center justify-center gap-2 rounded-xl border border-dashed border-white/15 p-4 text-sm font-semibold text-primary hover:bg-white/[.03]"><ImagePlus size={17}/>{uploading?'Uploading photo…':'Choose a photo'}<input data-testid="input-onboarding-photo" type="file" accept="image/*" disabled={uploading||data.photos.length>=6} className="hidden" onChange={e=>{void uploadOnboardingPhoto(e.currentTarget.files?.[0]);e.currentTarget.value=''}}/></label></div>}
{step===6&&<textarea data-testid="input-onboarding-bio" maxLength={500} rows={5} value={data.bio} onChange={e=>update('bio',e.target.value)} placeholder="A few things that make you, you…" className="field"/>}
{step===7&&<input data-testid="input-onboarding-country" value={data.country} onChange={e=>update('country',e.target.value)} placeholder="Country" className="field"/>}
{step===8&&<input data-testid="input-onboarding-state" value={data.state} onChange={e=>update('state',e.target.value)} placeholder="State or region" className="field"/>}
{step===9&&<input data-testid="input-onboarding-city" value={data.city} onChange={e=>update('city',e.target.value)} placeholder="City" className="field"/>}
{step===10&&<input data-testid="input-onboarding-interests" value={data.interests} onChange={e=>update('interests',e.target.value)} placeholder="Music, galleries, long walks" className="field"/>}
{step===11&&<div className="space-y-5"><div className="grid grid-cols-2 gap-3"><Field label="Age from"><input data-testid="input-onboarding-age-min" type="number" min="18" value={data.ageMin} onChange={e=>update('ageMin',e.target.value)} className="field"/></Field><Field label="Age to"><input data-testid="input-onboarding-age-max" type="number" value={data.ageMax} onChange={e=>update('ageMax',e.target.value)} className="field"/></Field></div><Field label={`Distance · ${data.distanceKm} km`}><input data-testid="input-onboarding-distance" type="range" min="1" max="500" value={data.distanceKm} onChange={e=>update('distanceKm',Number(e.target.value))} className="w-full accent-[#f34e9a]"/></Field></div>}
</div>{error&&<p role="alert" data-testid="text-onboarding-error" className="mt-5 text-sm text-rose-300">{error}</p>}
<div className="mt-8 flex items-center justify-between border-t border-white/[.08] pt-5"><button disabled={step===0} onClick={()=>setStep(s=>Math.max(0,s-1))} data-testid="button-onboarding-back" className="rounded-xl border border-white/10 px-4 py-3 text-sm font-semibold disabled:opacity-35">Back</button><button disabled={saveDraft.isPending||saveProfile.isPending} onClick={()=>void next()} data-testid="button-onboarding-next" className="inline-flex items-center gap-2 rounded-xl bg-primary px-5 py-3 text-sm font-bold text-[#26111b] disabled:opacity-50">{step===11?'Finish setup':'Continue'}<ArrowRight size={16}/></button></div></div></div></PageFrame>}

function SettingsPage(){const health=useHealthCheck({query:{queryKey:getHealthCheckQueryKey(),refetchInterval:60000}});const q=useGetVibeSwipeSettings({query:{queryKey:getGetVibeSwipeSettingsQueryKey()}});const update=useUpdateVibeSwipeSettings();const qc=useQueryClient();const [city,setCity]=useState('');useEffect(()=>{if(q.data?.travelCity)setCity(q.data.travelCity)},[q.data?.travelCity]);async function save(data:{incognito:boolean;travelMode:boolean;travelCity:string|null}){try{await update.mutateAsync({data});await qc.invalidateQueries({queryKey:getGetVibeSwipeSettingsQueryKey()})}catch{window.alert('Settings could not be saved. Try again.')}}
return <PageFrame><PageHeading eyebrow="Your comfort" title="Settings" description="Control how you show up and where you discover."/><div className="max-w-2xl space-y-4"><div className="flex items-center gap-2 px-1 text-xs text-muted-foreground" data-testid="status-api-health"><span className={`h-2 w-2 rounded-full ${health.data?.status==='ok'?'bg-emerald-400':health.isError?'bg-rose-400':'bg-amber-300'}`}/>{health.data?.status==='ok'?'VibeSwipe services are connected':health.isError?'Service status unavailable':'Checking service status'}</div><div className="rounded-2xl border border-white/[.08] bg-card p-5"><div className="flex items-center gap-4"><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-accent text-primary"><EyeOff size={18}/></div><div className="flex-1"><h3 className="font-bold">Incognito mode</h3><p className="mt-1 text-xs text-muted-foreground">Only people you like can see your profile.</p></div><input type="checkbox" aria-label="Incognito mode" data-testid="toggle-incognito" checked={q.data?.incognito??false} disabled={update.isPending||q.isLoading} onChange={e=>void save({incognito:e.target.checked,travelMode:q.data?.travelMode??false,travelCity:q.data?.travelCity??null})} className="h-5 w-5 accent-[#f34e9a]"/></div></div>
<div className="rounded-2xl border border-white/[.08] bg-card p-5"><div className="flex items-center gap-4"><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-accent text-primary"><Navigation size={18}/></div><div className="flex-1"><h3 className="font-bold">Travel mode</h3><p className="mt-1 text-xs text-muted-foreground">Discover people in another city.</p></div><input type="checkbox" aria-label="Travel mode" data-testid="toggle-travel-mode" checked={q.data?.travelMode??false} disabled={!q.data?.travelCity||update.isPending} onChange={e=>void save({incognito:q.data?.incognito??false,travelMode:e.target.checked,travelCity:q.data?.travelCity??null})} className="h-5 w-5 accent-[#f34e9a]"/></div><div className="mt-5 flex gap-2"><input data-testid="input-travel-city" value={city} onChange={e=>setCity(e.target.value)} placeholder="Search a city" className="field"/><button onClick={()=>void save({incognito:q.data?.incognito??false,travelMode:q.data?.travelMode??false,travelCity:city.trim()||null})} data-testid="button-save-travel-city" className="shrink-0 rounded-xl bg-secondary px-4 text-sm font-bold">Save city</button></div></div>
<div className="rounded-2xl border border-white/[.08] bg-card p-5"><div className="flex items-start gap-3"><Shield size={19} className="mt-1 text-[#8ed9b7]"/><div><h3 className="font-bold">Your safety matters</h3><p className="mt-1 text-xs leading-5 text-muted-foreground">Block and report from a profile or conversation. Blocking prevents contact. Unmatching ends a mutual connection and shared chat.</p><Link href="/matches" data-testid="link-safety-matches" className="mt-3 inline-block text-xs font-bold text-primary">Manage blocked profiles</Link></div></div></div>
<div className="rounded-2xl border border-white/[.08] bg-card p-5"><div className="flex items-center justify-between gap-4"><div><h3 className="font-bold">Install VibeSwipe</h3><p className="mt-1 text-xs text-muted-foreground">Add a shortcut to your Android home screen.</p></div><InstallAction/></div></div>
{q.isError&&<Retry onRetry={()=>void q.refetch()} text="Settings could not load."/>}</div></PageFrame>}

function PublicProfile({id}:{id:string}){const q=useGetProfileById(id,{query:{queryKey:getGetProfileByIdQueryKey(id)}});const view=useRecordProfileView();const seen=useRef('');useEffect(()=>{if(q.data?.id&&seen.current!==q.data.id){seen.current=q.data.id;view.mutate({profileId:q.data.id})}},[q.data?.id]);return <PageFrame>{q.isLoading?<Busy/>:q.isError||!q.data?<Retry onRetry={()=>void q.refetch()} text="Profile unavailable."/>:<><PageHeading eyebrow="A closer look" title={`${q.data.name}, ${q.data.age}`} description={[q.data.city,q.data.country].filter(Boolean).join(', ')}/><div className="max-w-2xl rounded-3xl border border-white/10 bg-card p-6"><p className="leading-7 text-muted-foreground">{q.data.bio}</p><div className="mt-5 flex flex-wrap gap-2">{q.data.interests.map(i=><span key={i} className="rounded-full bg-accent px-3 py-2 text-xs text-[#ffafd1]">{i}</span>)}</div><Link href="/discover" data-testid="link-public-profile-discover" className="mt-6 inline-flex rounded-xl bg-primary px-4 py-3 text-sm font-bold text-[#26111b]">Discover profiles</Link></div></>}</PageFrame>}

function OnboardingGate(){const p=useGetMyProfile();if(p.isLoading)return <PageFrame><Busy/></PageFrame>;if(p.data)return <Redirect to="/discover"/>;return <OnboardingPage/>}
function HomeRedirect(){return <><Show when="signed-in"><Redirect to="/discover"/></Show><Show when="signed-out"><Landing/></Show></>}
function RouteShell({component:Component}:{component:()=>ReactNode}){return <ShellPage><Component/></ShellPage>}
function ChatRoute(){const params=useParams<{matchId:string}>();return <ShellPage><ChatPage matchId={params.matchId||''}/></ShellPage>}
function OnboardingRoute(){return <ShellPage><OnboardingGate/></ShellPage>}
function ProfileRoute(){return <ShellPage><ProfilePage/></ShellPage>}
function SettingsRoute(){return <ShellPage><SettingsPage/></ShellPage>}
function DiscoverRoute(){return <ShellPage><DiscoverPage/></ShellPage>}
function MatchesRoute(){return <ShellPage><MatchesPage/></ShellPage>}
function ViewsRoute(){return <ShellPage><ViewsPage/></ShellPage>}
function NotificationsRoute(){return <ShellPage><NotificationsPage/></ShellPage>}
function PublicProfileRoute(){const [loc]=useLocation();return <ShellPage><PublicProfile id={loc.split('/').pop()||''}/></ShellPage>}
function ClerkCacheSync(){const {user}=useUser();const client=useQueryClient();const previous=useRef<string|null|undefined>(undefined);useEffect(()=>{const id=user?.id??null;if(previous.current!==undefined&&previous.current!==id)client.clear();previous.current=id},[user?.id,client]);return null}
function ClerkRoutes(){const [,setLocation]=useLocation();return <ClerkProvider publishableKey={clerkPubKey} proxyUrl={clerkProxyUrl} appearance={appearance} signInUrl={pathFor('/sign-in')} signUpUrl={pathFor('/sign-up')} localization={{signIn:{start:{title:'Welcome back',subtitle:'Your next good conversation is waiting.'}},signUp:{start:{title:'Make room for a spark',subtitle:'Create your adults-only VibeSwipe account.'}}}} routerPush={to=>setLocation(to.startsWith(basePath)?to.slice(basePath.length)||'/':to)} routerReplace={to=>setLocation(to.startsWith(basePath)?to.slice(basePath.length)||'/':to,{replace:true})}><ClerkCacheSync/><Switch>
  <Route path="/" component={HomeRedirect}/>
  <Route path="/sign-in/*?"><div className="grain flex min-h-[100dvh] items-center justify-center bg-background px-4 py-10"><div className="fixed left-6 top-6"><Brand/></div><SignIn routing="path" path={pathFor('/sign-in')} signUpUrl={pathFor('/sign-up')}/></div></Route>
  <Route path="/sign-up/*?"><div className="grain flex min-h-[100dvh] items-center justify-center bg-background px-4 py-10"><div className="fixed left-6 top-6"><Brand/></div><SignUp routing="path" path={pathFor('/sign-up')} signInUrl={pathFor('/sign-in')}/></div></Route>
  <Route path="/onboarding" component={OnboardingRoute}/><Route path="/discover" component={DiscoverRoute}/><Route path="/matches" component={MatchesRoute}/>
  <Route path="/chat/:matchId" component={ChatRoute}/><Route path="/views" component={ViewsRoute}/><Route path="/notifications" component={NotificationsRoute}/>
  <Route path="/profile" component={ProfileRoute}/><Route path="/profile/:profileId" component={PublicProfileRoute}/><Route path="/settings" component={SettingsRoute}/><Route component={NotFound}/>
</Switch></ClerkProvider>}
function App(){if(!clerkPubKey)throw new Error('Missing VITE_CLERK_PUBLISHABLE_KEY');return <QueryClientProvider client={queryClient}><WouterRouter base={basePath}><ClerkRoutes/></WouterRouter></QueryClientProvider>}
export default App;
